package com.shrija.audit.controller; import com.shrija.audit.dto.*; import com.shrija.audit.service.AuditConversationService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/audit") public class AuditController { private final AuditConversationService service; public AuditController(AuditConversationService service){this.service=service;} @PostMapping("/chat") public ResponseEntity<AuditChatResponse> chat(@Valid @RequestBody AuditChatRequest r){var x=service.converse(r);return ResponseEntity.ok(new AuditChatResponse(x.sessionId(),x.responseText()));} }
